// --- AUTENTIKASI SESI ---
function getCurrentUser() {
  const savedUser = localStorage.getItem('kasir_pintar_current_user');
  if (savedUser) {
    try {
      return JSON.parse(savedUser);
    } catch (e) {
      return null;
    }
  }
  return null;
}

function checkAuth(allowRedirect = true) {
  const user = getCurrentUser();
  if (!user && allowRedirect) {
    window.location.href = 'login.html';
    return null;
  }
  return user;
}

function logout() {
  localStorage.removeItem('kasir_pintar_current_user');
  window.location.href = 'login.html';
}

// --- UTILITAS FORMAT & SUARA ---
function formatRupiah(number) {
  if (isNaN(number)) number = 0;
  return 'Rp ' + Number(number).toLocaleString('id-ID');
}

function numberToWordsIndonesian(number) {
  number = Math.floor(Math.abs(number));
  if (number === 0) return 'Nol rupiah';

  const satuan = ['', 'satu', 'dua', 'tiga', 'empat', 'lima', 'enam', 'tujuh', 'delapan', 'sembilan', 'sepuluh', 'sebelas'];

  function terbilang(n) {
    if (n < 12) return satuan[n];
    if (n < 20) return terbilang(n - 10) + ' belas';
    if (n < 100) return terbilang(Math.floor(n / 10)) + ' puluh ' + terbilang(n % 10);
    if (n < 200) return 'seratus ' + terbilang(n - 100);
    if (n < 1000) return terbilang(Math.floor(n / 100)) + ' ratus ' + terbilang(n % 100);
    if (n < 2000) return 'seribu ' + terbilang(n - 1000);
    if (n < 1000000) return terbilang(Math.floor(n / 1000)) + ' ribu ' + terbilang(n % 1000);
    if (n < 1000000000) return terbilang(Math.floor(n / 1000000)) + ' juta ' + terbilang(n % 1000000);
    return terbilang(Math.floor(n / 1000000000)) + ' milyar ' + terbilang(n % 1000000000);
  }

  const result = terbilang(number).trim().replace(/\s+/g, ' ');
  return result.charAt(0).toUpperCase() + result.slice(1) + ' rupiah';
}

// --- AUDIO ENGINE (SUARA TENANG TETESAN AIR & PEMBAYARAN BERHASIL / TIDAK BERHASIL) ---
let audioCtx = null;
let audioEnabled = localStorage.getItem('pos_sound_enabled') !== 'false';

function getAudioContext() {
  if (!audioCtx) {
    const AudioContextClass = window.AudioContext || window.webkitAudioContext;
    if (AudioContextClass) {
      audioCtx = new AudioContextClass();
    }
  }
  if (audioCtx && audioCtx.state === 'suspended') {
    audioCtx.resume();
  }
  return audioCtx;
}

// 1. Suara Tenang Tetesan Air saat klik fitur (Dinonaktifkan: hening saat mengklik)
function playWaterDropSound() {
  // Hening total saat mengklik
  return;
}

// 2. Suara Pembayaran Berhasil (Melodi Chime Tenang & Riak Air Berhasil)
function playPaymentSuccessSound() {
  if (!audioEnabled) return;
  try {
    const ctx = getAudioContext();
    if (!ctx) return;
    const now = ctx.currentTime;

    // Arpeggio harmonik nada mayor pentatonik lembut (C5, E5, G5, C6)
    const chords = [
      { f: 523.25, t: 0.00, d: 0.32, v: 0.14 },
      { f: 659.25, t: 0.08, d: 0.32, v: 0.15 },
      { f: 783.99, t: 0.16, d: 0.35, v: 0.16 },
      { f: 1046.50, t: 0.24, d: 0.50, v: 0.18 }
    ];

    chords.forEach(c => {
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = 'sine';
      osc.frequency.setValueAtTime(c.f, now + c.t);

      gain.gain.setValueAtTime(0.001, now + c.t);
      gain.gain.linearRampToValueAtTime(c.v, now + c.t + 0.015);
      gain.gain.exponentialRampToValueAtTime(0.001, now + c.t + c.d);

      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.start(now + c.t);
      osc.stop(now + c.t + c.d);
    });

    // Sentuhan riak air penenang di akhir konfirmasi
    setTimeout(() => {
      playWaterDropSound();
    }, 280);
  } catch (e) {
    console.log('Audio error:', e);
  }
}

// 3. Suara Pembayaran Tidak Berhasil (Nada Peringatan Lembut Rendah & Tetes Redup)
function playPaymentFailSound() {
  if (!audioEnabled) return;
  try {
    const ctx = getAudioContext();
    if (!ctx) return;
    const now = ctx.currentTime;

    const filter = ctx.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.setValueAtTime(950, now);

    // Nada peringatan 1 (320Hz menurun)
    const osc1 = ctx.createOscillator();
    const gain1 = ctx.createGain();
    osc1.type = 'triangle';
    osc1.frequency.setValueAtTime(320, now);
    osc1.frequency.exponentialRampToValueAtTime(270, now + 0.18);

    gain1.gain.setValueAtTime(0.001, now);
    gain1.gain.linearRampToValueAtTime(0.18, now + 0.015);
    gain1.gain.exponentialRampToValueAtTime(0.001, now + 0.24);

    osc1.connect(filter);
    filter.connect(gain1);
    gain1.connect(ctx.destination);

    osc1.start(now);
    osc1.stop(now + 0.25);

    // Nada peringatan 2 (210Hz redup dengan riak tenang penanda belum berhasil)
    const osc2 = ctx.createOscillator();
    const gain2 = ctx.createGain();
    const t2 = now + 0.16;
    osc2.type = 'sine';
    osc2.frequency.setValueAtTime(210, t2);
    osc2.frequency.exponentialRampToValueAtTime(160, t2 + 0.22);

    gain2.gain.setValueAtTime(0.001, t2);
    gain2.gain.linearRampToValueAtTime(0.16, t2 + 0.02);
    gain2.gain.exponentialRampToValueAtTime(0.001, t2 + 0.28);

    osc2.connect(filter);
    gain2.connect(ctx.destination);

    osc2.start(t2);
    osc2.stop(t2 + 0.3);
  } catch (e) {
    console.log('Audio error:', e);
  }
}

// Dispatcher Suara Utama
function playSound(type = 'water') {
  if (!audioEnabled) return;
  // Hilangkan suara saat mengklik fitur / tombol / tautan
  if (type === 'water' || type === 'click' || type === 'drop' || type === 'beep' || type === 'feature') {
    return;
  } else if (type === 'payment_success' || type === 'success') {
    playPaymentSuccessSound();
  } else if (type === 'payment_fail' || type === 'error' || type === 'fail') {
    playPaymentFailSound();
  }
}

// Toggle On/Off Suara dengan Notifikasi
function toggleAudio() {
  audioEnabled = !audioEnabled;
  localStorage.setItem('pos_sound_enabled', audioEnabled ? 'true' : 'false');

  const btn = document.getElementById('soundToggleBtn');
  const icon = document.getElementById('soundIcon');
  if (btn) {
    btn.classList.toggle('muted', !audioEnabled);
    btn.setAttribute('title', audioEnabled ? 'Audio Aktif (Klik untuk Mematikan)' : 'Audio Mati (Klik untuk Mengaktifkan)');
  }
  if (icon) {
    icon.setAttribute('data-lucide', audioEnabled ? 'volume-2' : 'volume-x');
    if (window.lucide) lucide.createIcons();
  }

  if (audioEnabled) {
    showToast('Notifikasi audio sistem diaktifkan', 'info');
  } else {
    showToast('Suara efek audio dimatikan', 'info');
  }
}

// Suara klik otomatis dinonaktifkan sesuai permintaan pengguna

// --- NOTIFIKASI KHUSUS HASIL PEMBAYARAN (BERHASIL & TIDAK BERHASIL) ---
function showPaymentNotification(isSuccess, message, details = {}) {
  // Hapus jika ada notifikasi sebelumnya
  const oldModal = document.getElementById('paymentResultModal');
  if (oldModal) oldModal.remove();

  const overlay = document.createElement('div');
  overlay.id = 'paymentResultModal';
  overlay.className = 'payment-notif-overlay';

  const card = document.createElement('div');
  card.className = `payment-notif-card ${isSuccess ? 'success' : 'failed'}`;

  if (isSuccess) {
    card.innerHTML = `
      <div class="payment-notif-header">
        <div class="notif-icon-circle">
          <i data-lucide="check-circle-2" style="width: 36px; height: 36px;"></i>
        </div>
        <h3 class="notif-title">PEMBAYARAN BERHASIL!</h3>
        <p class="notif-subtitle">Transaksi telah sukses diverifikasi & tercatat di sistem</p>
      </div>

      <div class="payment-notif-body">
        <div class="payment-notif-detail-box">
          <div class="payment-notif-row">
            <span>No. Faktur</span>
            <strong class="font-mono">${details.invoice || '-'}</strong>
          </div>
          <div class="payment-notif-row">
            <span>Metode Bayar</span>
            <strong style="color: var(--teal-700);">${details.method || 'TUNAI'}</strong>
          </div>
          <div class="payment-notif-row">
            <span>Total Tagihan</span>
            <strong>${formatRupiah(details.total || 0)}</strong>
          </div>
          <div class="payment-notif-row">
            <span>Jumlah Diterima</span>
            <strong class="font-mono">${formatRupiah(details.received || details.total || 0)}</strong>
          </div>
          <div class="payment-notif-row highlight-row">
            <span>Kembalian</span>
            <strong class="font-mono" style="font-size: 1.15rem; color: #166534;">${formatRupiah(details.change || 0)}</strong>
          </div>
        </div>

        <div class="payment-notif-message-box info">
          <i data-lucide="info" style="width: 18px; height: 18px; flex-shrink: 0; margin-top: 2px;"></i>
          <span>${message || 'Struk transaksi telah disiapkan dan siap dicetak.'}</span>
        </div>

        <div class="payment-notif-footer">
          <button type="button" class="btn-notif-secondary" onclick="closePaymentNotification()">Tutup</button>
          <button type="button" class="btn-notif-primary-success" onclick="closePaymentNotification(); if (typeof showReceiptModal === 'function' && window.lastCompletedSale) showReceiptModal(window.lastCompletedSale);">
            <i data-lucide="printer"></i>
            <span>Lihat Struk Transaksi</span>
          </button>
        </div>
      </div>
    `;
  } else {
    card.innerHTML = `
      <div class="payment-notif-header">
        <div class="notif-icon-circle">
          <i data-lucide="alert-circle" style="width: 36px; height: 36px;"></i>
        </div>
        <h3 class="notif-title">PEMBAYARAN TIDAK BERHASIL!</h3>
        <p class="notif-subtitle">Transaksi tidak dapat diproses atau uang belum mencukupi</p>
      </div>

      <div class="payment-notif-body">
        <div class="payment-notif-message-box warning">
          <i data-lucide="alert-triangle" style="width: 20px; height: 20px; flex-shrink: 0; margin-top: 2px; color: #dc2626;"></i>
          <div>
            <strong style="display: block; margin-bottom: 3px; font-size: 0.92rem; color: #991b1b;">Kendala Pembayaran:</strong>
            <span>${message || 'Nominal pembayaran tidak sesuai atau terjadi pembatalan.'}</span>
          </div>
        </div>

        ${details.shortage ? `
          <div class="payment-notif-detail-box" style="background: #fff1f2; border-color: #fecdd3;">
            <div class="payment-notif-row">
              <span>Total Tagihan:</span>
              <strong class="font-mono">${formatRupiah(details.total || 0)}</strong>
            </div>
            <div class="payment-notif-row">
              <span>Uang Diterima:</span>
              <strong class="font-mono" style="color: #dc2626;">${formatRupiah(details.received || 0)}</strong>
            </div>
            <div class="payment-notif-row highlight-row" style="border-top-color: #fda4af;">
              <span style="color: #991b1b; font-weight: 800;">Kekurangan Uang:</span>
              <strong class="font-mono" style="color: #dc2626; font-size: 1.15rem;">-${formatRupiah(details.shortage)}</strong>
            </div>
          </div>
        ` : ''}

        <div class="payment-notif-footer">
          <button type="button" class="btn-notif-secondary" onclick="closePaymentNotification()">Tutup</button>
          <button type="button" class="btn-notif-primary-fail" onclick="closePaymentNotification(); focusPaymentInput();">
            <i data-lucide="refresh-cw"></i>
            <span>Perbaiki Nominal Bayar</span>
          </button>
        </div>
      </div>
    `;
  }

  overlay.appendChild(card);
  document.body.appendChild(overlay);

  if (window.lucide) lucide.createIcons();
}

function closePaymentNotification() {
  const modal = document.getElementById('paymentResultModal');
  if (modal) {
    modal.style.opacity = '0';
    modal.style.transition = 'opacity 0.2s';
    setTimeout(() => modal.remove(), 200);
  }
}

function focusPaymentInput() {
  const input = document.getElementById('cashReceivedInput');
  if (input) {
    input.focus();
    input.select();
    input.classList.remove('input-error-shake');
    void input.offsetWidth; // Trigger reflow
    input.classList.add('input-error-shake');
  }
}

// --- NOTIFIKASI TOAST ---
function showToast(message, type = 'info') {
  let container = document.getElementById('toastContainer');
  if (!container) {
    container = document.createElement('div');
    container.id = 'toastContainer';
    container.className = 'toast-container';
    document.body.appendChild(container);
  }

  const toast = document.createElement('div');
  toast.className = `toast ${type}`;

  let iconName = 'info';
  if (type === 'success') iconName = 'check-circle-2';
  else if (type === 'error') iconName = 'alert-circle';

  toast.innerHTML = `
    <i data-lucide="${iconName}"></i>
    <span>${message}</span>
  `;

  container.appendChild(toast);
  if (window.lucide) lucide.createIcons();

  setTimeout(() => {
    toast.style.opacity = '0';
    toast.style.transform = 'translateX(50px)';
    toast.style.transition = 'all 0.3s ease';
    setTimeout(() => toast.remove(), 300);
  }, 3500);
}

// --- TOGGLE INTERAKSI LAYOUT (DESKTOP & HP / MOBILE) ---
function toggleSidebar() {
  const layout = document.querySelector('.app-layout');
  const isMobile = window.innerWidth <= 768;
  if (isMobile) {
    if (layout) layout.classList.toggle('sidebar-mobile-open');
    document.body.classList.toggle('sidebar-mobile-open');
  } else {
    if (layout) layout.classList.toggle('sidebar-collapsed');
  }
}

function closeMobileSidebar() {
  const layout = document.querySelector('.app-layout');
  if (layout) layout.classList.remove('sidebar-mobile-open');
  document.body.classList.remove('sidebar-mobile-open');
}

function toggleNotifDropdown() {
  const drop = document.getElementById('notifDropdown');
  if (drop) {
    drop.style.display = drop.style.display === 'none' || !drop.style.display ? 'block' : 'none';
  }
  const userDrop = document.getElementById('userDropdown');
  if (userDrop) userDrop.style.display = 'none';
}

function toggleUserDropdown() {
  const drop = document.getElementById('userDropdown');
  if (drop) {
    drop.style.display = drop.style.display === 'none' || !drop.style.display ? 'block' : 'none';
  }
  const notifDrop = document.getElementById('notifDropdown');
  if (notifDrop) notifDrop.style.display = 'none';
}

// Tutup dropdown saat klik di luar
document.addEventListener('click', (e) => {
  if (!e.target.closest('.notif-dropdown-wrapper')) {
    const notifDrop = document.getElementById('notifDropdown');
    if (notifDrop) notifDrop.style.display = 'none';
  }
  if (!e.target.closest('.user-profile-wrapper')) {
    const userDrop = document.getElementById('userDropdown');
    if (userDrop) userDrop.style.display = 'none';
  }
});

