// --- MODAL LIGHTBOX PRATINJAU GAMBAR (BISA DILIHAT & DIPERBESAR) ---
function openImagePreview(src, title = 'Foto Produk', price = '') {
  if (!src) return;

  let modal = document.getElementById('imageLightboxModal');
  if (!modal) {
    modal = document.createElement('div');
    modal.id = 'imageLightboxModal';
    modal.className = 'modal-overlay';
    modal.style.display = 'none';
    modal.innerHTML = `
      <div class="image-preview-modal-card">
        <div class="image-preview-header">
          <div>
            <h3 id="lightboxTitle">Foto Produk</h3>
            <span id="lightboxPrice" class="font-mono font-bold" style="color: var(--teal-800); font-size: 0.9rem;"></span>
          </div>
          <button type="button" class="modal-close-btn" onclick="closeImagePreview()">&times;</button>
        </div>
        <div class="image-preview-body">
          <img id="lightboxImg" class="image-preview-large-img" src="" alt="Pratinjau Foto" />
        </div>
        <div class="image-preview-footer">
          <span style="font-size: 0.78rem; color: #64748b;">Klik di luar atau tombol &times; untuk menutup</span>
          <button type="button" class="btn-cancel-pay" onclick="closeImagePreview()">Tutup</button>
        </div>
      </div>
    `;
    modal.onclick = (e) => {
      if (e.target === modal) closeImagePreview();
    };
    document.body.appendChild(modal);
  }

  document.getElementById('lightboxTitle').textContent = title;
  document.getElementById('lightboxPrice').textContent = price ? formatRupiah(price) : '';
  const img = document.getElementById('lightboxImg');
  img.src = src;
  modal.style.display = 'flex';
  playSound('click');
}

function closeImagePreview() {
  const modal = document.getElementById('imageLightboxModal');
  if (modal) modal.style.display = 'none';
}

// Global Fallback showToast untuk seluruh halaman sistem
if (typeof window.showToast !== 'function') {
  window.showToast = function(message, type = 'info') {
    let container = document.getElementById('toastContainer');
    if (!container) {
      container = document.createElement('div');
      container.id = 'toastContainer';
      container.style.cssText = 'position:fixed;top:20px;right:20px;z-index:999999;display:flex;flex-direction:column;gap:10px;pointer-events:none;max-width:380px;width:calc(100% - 40px);';
      document.body.appendChild(container);
    }
    const toast = document.createElement('div');
    toast.style.cssText = 'pointer-events:auto;display:flex;align-items:center;gap:12px;padding:14px 18px;border-radius:12px;font-family:inherit;font-size:13px;font-weight:600;box-shadow:0 10px 25px rgba(0,0,0,0.25);transition:all 0.3s cubic-bezier(0.16, 1, 0.3, 1);transform:translateX(50px);opacity:0;';
    
    if (type === 'success') {
      toast.style.background = '#064e3b';
      toast.style.color = '#ecfdf5';
      toast.style.border = '1px solid #059669';
    } else if (type === 'error' || type === 'danger') {
      toast.style.background = '#7f1d1d';
      toast.style.color = '#fef2f2';
      toast.style.border = '1px solid #dc2626';
    } else if (type === 'warning') {
      toast.style.background = '#78350f';
      toast.style.color = '#fffbeb';
      toast.style.border = '1px solid #d97706';
    } else {
      toast.style.background = '#064e3b';
      toast.style.color = '#ecfdf5';
      toast.style.border = '1px solid #10b981';
    }
    
    toast.innerHTML = `<span style="line-height:1.4;flex:1;">${message}</span>`;
    container.appendChild(toast);
    
    requestAnimationFrame(() => {
      toast.style.transform = 'translateX(0)';
      toast.style.opacity = '1';
    });
    
    setTimeout(() => {
      toast.style.transform = 'translateX(50px)';
      toast.style.opacity = '0';
      setTimeout(() => toast.remove(), 350);
    }, 3500);
  };
}
